func (this *Test_org_eclipse_swt_widgets_Text) DoSegmentsTest(isListening bool) {
	var string_ string = "1234"
	this.text.SetText(string_)
	junit.AssertEquals(isListening, this.listenerCalled)
	this.listenerCalled = false
	junit.AssertEquals(string_, this.text.GetText())
	var substr string = "56"
	this.text.Append(substr)
	string_ += substr
	junit.AssertEquals(isListening, this.listenerCalled)
	this.listenerCalled = false
	junit.AssertEquals(string_, this.text.GetText())
	if (this.text.GetStyle() & swt.SINGLE) != 0 {
		var limit int32 = jrt.StringLength(string_) - 1
		this.text.SetTextLimit(limit)
		junit.AssertEquals(int32(limit), int32(this.text.GetTextLimit()))
		this.text.SetText(string_)
		junit.AssertEquals(jrt.Substring(string_, 0, limit), this.text.GetText())
	}
	this.text.SetTextLimit(swt.TextLIMIT)
	this.text.SetText(string_)
	junit.AssertEquals(string_, this.text.GetText())
	this.listenerCalled = false
	var pt *swt.Point = swt.NewPoint(1, 3)
	this.text.SetSelectionSelection(pt)
	junit.AssertEquals(pt, this.text.GetSelection())
	junit.AssertFalse(this.listenerCalled)
	this.CopyToClipboard(this.text)
	junit.AssertEquals(isListening, this.listenerCalled)
	this.listenerCalled = false
	substr = jrt.Substring(string_, pt.X, pt.Y)
	pt.Y = 1
	pt.X = pt.Y
	this.text.SetSelectionSelection(pt)
	this.PasteFromClipboard(this.text)
	junit.AssertEquals(isListening, this.listenerCalled)
	this.listenerCalled = false
	junit.AssertEquals(fmt.Sprintf("%s%s%s", jrt.Substring(string_, 0, pt.X), substr, jrt.Substring(string_, pt.Y, -1)), this.text.GetText())
	pt.Y = pt.X + jrt.StringLength(substr)
	pt.X = pt.Y
	junit.AssertEquals(pt, this.text.GetSelection())
	pt.X -= 2
	this.text.SetSelectionSelection(pt)
	junit.AssertEquals(substr, this.text.GetSelectionText())
	junit.AssertEquals(substr, this.text.GetTextStartEnd(pt.X, pt.Y-1))
	this.CutToClipboard(this.text)
	junit.AssertEquals(isListening, this.listenerCalled)
	this.listenerCalled = false
	junit.AssertEquals(string_, this.text.GetText())
	substr = "12"
	pt.X = 6
	pt.Y = 8
	this.text.SetSelectionStartEnd(pt.X, pt.Y)
	this.CutToClipboard(this.text)
	pt.Y = pt.X
	junit.AssertEquals(pt, this.text.GetSelection())
	this.listenerCalled = false
	pt.Y = 0
	pt.X = pt.Y
	this.text.SetSelectionSelection(pt)
	this.text.Insert(substr)
	junit.AssertEquals(isListening, this.listenerCalled)
	this.listenerCalled = false
	pt.Y = pt.X + jrt.StringLength(substr)
	pt.X = pt.Y
	junit.AssertEquals(pt, this.text.GetSelection())
	junit.AssertEquals(fmt.Sprintf("%s%s", substr, string_), this.text.GetText())
}

